func (syncgoCtx *Context) typecheckargs(n ir.InitNode) {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	var list []ir.Node
	switch n := n.(type) {
	default:
		syncgoCtx.fatalf("typecheckargs %+v", n.Op())
	case *ir.CallExpr:
		list = n.Args
		if n.IsDDD {
			syncgoCtx.Exprs(list)
			return
		}
	case *ir.ReturnStmt:
		list = n.Results
	}
	if len(list) != 1 {
		syncgoCtx.Exprs(list)
		return
	}

	syncgoCtx.typecheckslice(list, ctxExpr|ctxMultiOK)
	t := list[0].Type()
	if t == nil || !t.IsFuncArgStruct() {
		return
	}

	// Rewrite f(g()) into t1, t2, ... = g(); f(t1, t2, ...).
	syncgoCtx.RewriteMultiValueCall(n, list[0])
}

// RewriteNonNameCall replaces non-Name call expressions with temps,
// rewriting f()(...) to t0 := f(); t0(...).
func (syncgoCtx *Context) RewriteNonNameCall(n *ir.CallExpr) {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	np := &n.Fun
	if dot, ok := (*np).(*ir.SelectorExpr); ok && (dot.Op() == ir.ODOTMETH || dot.Op() == ir.ODOTINTER || dot.Op() == ir.OMETHVALUE) {
		np = &dot.X // peel away method selector
	}

	// Check for side effects in the callee expression.
	// We explicitly special case new(T) though, because it doesn't have
	// observable side effects, and keeping it in place allows better escape analysis.
	if !ir.Any(*np, func(n ir.Node) bool { return n.Op() != ir.ONEW && callOrChan(n) }) {
		return
	}

	tmp := syncgoCtx.TempAt(syncgoCtx.IR.Types.Pos, syncgoCtx.IR.CurFunc, (*np).Type())
	as := syncgoCtx.IR.NewAssignStmt(syncgoCtx.IR.Types.Pos, tmp, *np)
	as.PtrInit().Append(syncgoCtx.Stmt(syncgoCtx.IR.NewDecl(n.Pos(), ir.ODCL, tmp)))
	*np = tmp

	n.PtrInit().Append(syncgoCtx.Stmt(as))
}

